// === Tab: tab2 ===
class Smoke {
	constructor(tex, pos = {
		x: 0,
		y: 0
	}, dir = {
		x: 1,
		y: 1
	}) {
		this.current_time = 0.0;
		this.duration = 3.0; // seconds
		this.target_scale = random(1.0, 1.2);
		this.ratio = 0;
		this.texture = tex;
		this.pos = pos;
		this.dir = dir;
		this.angle = random(-PI, PI);
		this.birthT = millis();
		imageMode(CENTER);
	}

	done() {
		return this.ratio > 1.0;
	}

	draw() {
		if (!this.done()) {
			this.current_time = (millis() - this.birthT) / 1000;
			this.ratio = .5 * this.current_time / this.duration;
			let t_scale = this.smoothStop(this.ratio, 2);
			let t_angle = this.smoothStop(this.ratio, 3);
			let t_opacity = (.6 - this.ratio) * 255;
			this.pos.x += this.smoothStop(this.ratio, 9) * this.dir.x;
			this.pos.y += this.smoothStop(this.ratio, 9) * this.dir.y;
			push();
			translate(this.pos.x, this.pos.y);
			rotate(t_angle);
			scale(t_scale * this.target_scale);
			tint(255, t_opacity);
			image(this.texture, 0, 0);
			pop();
		}
	}

	flip(x) {
		return 1 - x;
	}

	dumbPow(x, p) {
		let res = 1.0;
		for (let i = p; i--;) {
			res *= x;
		}

		return res;
	}

	smoothStop(t, power) {
		return this.flip(this.dumbPow(this.flip(t), power));
	}
}

// === Tab: tab3 ===
class smokeGenerator {

	constructor() {
		this.particles = [];
	}

	getSize() {
		return this.particles.length;
	}
	create(tex, pos, vel) {
		let obj = new Smoke(
			tex, {
				x: pos.x,
				y: pos.y
			}, {
				x: vel.x,
				y: vel.y
			}
		);
		this.particles.push(obj);
	}

	draw() {
		const iMax = this.particles.length;
		let i = 0;
		for (;i < iMax; i++) {
			this.particles[i].draw();
		}

		this.removeDeadParticles();

	}

	removeDeadParticles() {
		var i = 0;
		var iMax = this.particles.length;
		//var dead = this.particles.some();
		for(; i < iMax; i++) {
			if(this.particles[i].done()) {
				this.particles.splice(i,1);
				break;
			}
		}
		//this.particles.some(this.isDeadOrAlive);
	}

	isDeadOrAlive(obj,index,array) {
		if(obj.done()) {
			array.splice(index,1);
		}
	}
}

